from base import *
import json
ok=Check()
def abrir_caixa(pg):
    pg.click('button:has-text("Abrir caixa")');pg.wait_for_selector('.dg form');pg.click('.dg button:has-text("Abrir caixa")');pg.wait_for_timeout(250)
def vender(pg,carrinho,metodo='Dinheiro'):
    pg.evaluate(f"cart={carrinho};DESC=0;show('pdv')");pg.click('button:has-text("Pagamento (F5)")');pg.wait_for_selector('.dg');pg.click(f'.dg [data-v="{metodo}"]');pg.wait_for_timeout(200)
    if metodo=='PIX':
        pg.check('#pxc');pg.click('.dg button:has-text("Confirmar recebimento")');pg.wait_for_timeout(200)
    pg.click('.dg button:has-text("Finalizar venda")');pg.wait_for_timeout(300)
def preencher_matriz(pg,i,cst_label,ncm,pis='49 – Outras operações de saída',un=None,icms=None):
    pg.click(f'button[data-a="edit"][data-k="matriz"][data-i="{i}"]');pg.wait_for_selector('.dg form')
    pg.fill('#d_ncm',ncm);pg.fill('#d_cfop','5102');pg.select_option('#d_origem',label='0 – Nacional');pg.select_option('#d_cst',label=cst_label)
    if icms: pg.fill('#d_icmsAliq',icms)
    pg.select_option('#d_pisCst',label=pis);pg.select_option('#d_cofinsCst',label=pis)
    pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
with sync_playwright() as p:
    b,ctx,pg,errs=start(p);setup(pg)
    nav(pg,'Fiscal')
    ok('aba Fiscal tem a integração SEFAZ, a matriz fiscal e os dados do emitente',all(x in pg.inner_text('#main') for x in ['Integração fiscal (SEFAZ)','Matriz fiscal dos produtos','Dados fiscais da empresa','HOMOLOGAÇÃO']))
    linhas=lambda:{r.query_selector('td').inner_text().split('\n')[0].strip():r.query_selector_all('td')[1].inner_text().strip() for r in pg.query_selector_all('table')[1].query_selector_all('tbody tr')} if False else None
    chk=lambda rid:pg.evaluate("(id)=>fiscChecks().find(c=>c.id==id).ok",rid)
    ok('CNPJ ativo já vem pronto (cartão CNPJ); IE, regime e matriz estão pendentes',chk('cnpj') and not chk('ie') and not chk('crt') and not chk('matriz') and 'Faltam' in pg.inner_text('.off'))
    ok('endereço do emitente (Av. Piracicaba, 584, Recife/PE, CEP) já cadastrado',chk('emitente'))
    # ── dados do emitente
    pg.click('button[data-n="emp"][data-v="fiscal"]');pg.wait_for_selector('.dg form')
    pg.fill('#d_uf','PERNAMBUCO');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(200)
    ok('UF com mais de 2 letras é recusada',pg.evaluate("EMP.uf")=='PE' and 'UF inválida' in pg.inner_text('#de'))
    pg.fill('#d_uf','PE');pg.fill('#d_cep','5079');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(200)
    ok('CEP incompleto é recusado',pg.evaluate("EMP.cep")=='50.790-205' and 'CEP deve ter 8' in pg.inner_text('#de'))
    pg.fill('#d_cep','50.790-205');pg.fill('#d_ie','0321418-40');pg.select_option('#d_crt',label='1 – Simples Nacional');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(300)
    ok('IE e regime (Simples Nacional) salvos',chk('ie') and chk('crt') and pg.evaluate("EMP.crt")=='1 – Simples Nacional')
    # ── venda ANTES da matriz fiscal: precisa mostrar pendências reais, não "autorizada"
    nav(pg,'PDV');abrir_caixa(pg);vender(pg,"[[0,2]]")
    txt=pg.inner_text('.dg .rc')
    ok('sem matriz fiscal: o cupom diz "NFC-e PENDENTE" (nada de autorização inventada)',('NFC-e PENDENTE' in txt) and ('autorizada' not in txt.lower()))
    ok('a venda vira linha "Pendente de dados" na aba Fiscal',pg.evaluate("T.fiscal.rows[0][0]=='NFC-e 1001'&&T.fiscal.rows[0][3]=='Pendente de dados'"))
    pg.click('.dg button:has-text("Conferir NFC-e")');pg.wait_for_selector('#nfj')
    d=pg.inner_text('.dg')
    ok('conferência lista as pendências do produto e da empresa-matriz fiscal',('Sem dados fiscais' in d) and 'não envia nada à SEFAZ' in d)
    j=json.loads(pg.inner_text('#nfj'))
    ok('JSON no formato FocusNFe mesmo com pendências (CNPJ, itens, total, forma de pagamento 01)',j['cnpj_emitente']=='69196200000168' and j['valor_total']=='149.80' and j['items'][0]['codigo_produto']=='LEI-001' and j['formas_pagamento'][0]['forma_pagamento']=='01' and j['inscricao_estadual_emitente']=='032141840')
    pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    # ── matriz fiscal
    nav(pg,'Fiscal')
    pg.click('button[data-a="edit"][data-k="matriz"][data-i="0"]');pg.wait_for_selector('.dg form');pg.fill('#d_ncm','123');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
    ok('NCM inválido é salvo como rascunho, mas o produto continua "Incompleto"',pg.evaluate("taxErr(0).some(x=>/NCM/.test(x.msg))") and 'Incompleto' in pg.inner_text('#t-matriz tbody tr:first-child'))
    pg.click('button[data-a="ver"][data-k="matriz"][data-i="0"]');pg.wait_for_selector('.dg');ok('"Visualizar" mostra o que falta no produto','NCM deve ter 8 dígitos' in pg.inner_text('.dg'));pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    pg.click('button[data-a="edit"][data-k="matriz"][data-i="0"]');pg.wait_for_selector('.dg form')
    ok('em empresa do Simples, a lista de CST oferece CSOSN (101, 102...) e marca os não suportados',any(x in pg.inner_text('#d_cst') for x in ['102 – Tributada sem permissão de crédito']) and '900 – Outros (ainda não suportado)' in pg.inner_text('#d_cst') and '00 – Tributada integralmente' not in pg.inner_text('#d_cst'))
    pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    CS='102 – Tributada sem permissão de crédito'
    preencher_matriz(pg,0,CS,'04011010');preencher_matriz(pg,1,CS,'20096100');preencher_matriz(pg,2,CS,'10063021');preencher_matriz(pg,3,CS,'04061010')
    ok('4 produtos com matriz completa → "Completo"',pg.evaluate("CAT.every((_,i)=>taxErr(i).length==0)") and chk('matriz'))
    # ── checklist e configuração
    for k in ['ieHab','cert','credHom','cscToken']: pg.check(f'input[data-fc="{k}"]');pg.wait_for_timeout(120)
    pg.fill('input[data-fcv="certVal"]','2027-09-30');pg.press('input[data-fcv="certVal"]','Tab');pg.wait_for_timeout(150)
    pg.check('input[data-fc="token"]');pg.wait_for_timeout(150)
    ok('ainda falta o ID do CSC: não está pronto',not chk('csc') and 'Faltam' in pg.inner_text('.off'))
    pg.click('button[data-n="fiscCfg"]');pg.wait_for_selector('.dg form');pg.fill('#d_serie','1');pg.fill('#d_csc','abc');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(200)
    ok('ID do CSC não numérico é recusado','numérico' in pg.inner_text('#de'))
    pg.fill('#d_csc','1');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(300)
    ok('com tudo confirmado: "Tudo pronto para emitir em HOMOLOGAÇÃO"','Tudo pronto' in pg.inner_text('.off') and pg.evaluate("FISC.cscId")=='1' and pg.evaluate("FISC.chk.certVal")=='2027-09-30')
    pg.click('button[data-n="fiscCfg"]');pg.wait_for_selector('.dg form');pg.select_option('#d_amb',label='PRODUÇÃO (notas valem de verdade)');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
    ok('PRODUÇÃO é bloqueada enquanto faltar o credenciamento de produção','credenciamento' in pg.inner_text('#de').lower() and pg.evaluate("FISC.amb")=='HOMOLOGACAO')
    pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    pg.check('input[data-fc="credProd"]');pg.wait_for_timeout(150)
    pg.click('button[data-n="fiscCfg"]');pg.wait_for_selector('.dg form');pg.select_option('#d_amb',label='PRODUÇÃO (notas valem de verdade)');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
    ok('com todos os requisitos, a produção pode ser liberada (e o selo fica vermelho)',pg.evaluate("FISC.amb")=='PRODUCAO' and pg.locator('.pill.er:has-text("PRODUÇÃO")').count()==1)
    pg.click('button[data-n="fiscCfg"]');pg.wait_for_selector('.dg form');pg.select_option('#d_amb',label='HOMOLOGAÇÃO (testes)');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(200)
    # ── venda COM matriz completa
    nav(pg,'PDV');vender(pg,"[[0,2],[3,0.35]]",'PIX')
    txt=pg.inner_text('.dg .rc');ok('com tudo completo: "NFC-e pronta para emissão"','NFC-e pronta para emissão' in txt)
    pg.click('.dg button:has-text("Conferir NFC-e")');pg.wait_for_selector('#nfj');j=json.loads(pg.inner_text('#nfj'))
    ok('JSON completo: 2 itens com NCM, CFOP 5102, CSOSN 102 e total R$ 167,27',len(j['items'])==2 and j['items'][0]['codigo_ncm']=='04011010' and j['items'][0]['icms_situacao_tributaria']=='102' and j['valor_total']=='167.27' and j['items'][1]['quantidade_comercial']=='0.350' and j['items'][1]['unidade_comercial']=='KG')
    ok('PIX é forma de pagamento 17 e a nota está "Dados completos"',j['formas_pagamento'][0]['forma_pagamento']=='17' and 'Dados completos para emissão' in pg.inner_text('.dg'))
    pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    # ── venda feita ANTES de completar a matriz: atualizar com a matriz atual
    nav(pg,'Fiscal')
    ok('a primeira venda (feita sem matriz) continua pendente',pg.evaluate("T.fiscal.rows.find(r=>r[0]=='NFC-e 1001')[3]")=='Pendente de dados')
    linha=pg.locator('#t-fiscal tbody tr:has-text("NFC-e 1001")');linha.locator('button.lk').click();pg.wait_for_selector('#nfj')
    ok('o botão da linha NFC-e abre a conferência (não "autoriza" nada)','conferência' in pg.inner_text('.dg h2') and pg.evaluate("T.fiscal.rows.find(r=>r[0]=='NFC-e 1001')[3]")=='Pendente de dados')
    pg.click('.dg button:has-text("Atualizar com a matriz atual")');pg.wait_for_selector('#nfj');pg.wait_for_timeout(200)
    ok('"Atualizar com a matriz atual" resolve as pendências e a linha vira "Aguardando emissão"',pg.evaluate("T.fiscal.rows.find(r=>r[0]=='NFC-e 1001')[3]")=='Aguardando emissão' and 'Dados completos para emissão' in pg.inner_text('.dg'))
    pg.keyboard.press('Escape');pg.evaluate("closeDlg()")
    # ── regime normal
    pg.click('button[data-n="emp"][data-v="fiscal"]');pg.wait_for_selector('.dg form');pg.select_option('#d_crt',label='3 – Regime Normal (Lucro Presumido ou Real)');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
    ok('regime normal: os produtos com CSOSN viram "Incompleto" (CSOSN não vale no regime normal)',not pg.evaluate("taxErr(0).length==0"))
    pg.click('button[data-a="edit"][data-k="matriz"][data-i="0"]');pg.wait_for_selector('.dg form')
    ok('regime normal: a lista passa a oferecer CST (00, 40, 41, 50)','00 – Tributada integralmente' in pg.inner_text('#d_cst') and '102 –' not in pg.inner_text('#d_cst'))
    pg.select_option('#d_cst',label='00 – Tributada integralmente');pg.fill('#d_icmsAliq','18');pg.select_option('#d_pisCst',label='01 – Tributável (alíquota básica)');pg.fill('#d_pisAliq','0,65');pg.select_option('#d_cofinsCst',label='01 – Tributável (alíquota básica)');pg.fill('#d_cofinsAliq','3');pg.click('.dg button:has-text("Salvar")');pg.wait_for_timeout(250)
    ok('CST 00 com ICMS 18%, PIS 0,65% e COFINS 3% fica completo',pg.evaluate("taxErr(0).length==0"))
    pg.evaluate("NFCE['NFC-e 1002'].tax={};NFCE['NFC-e 1002'].sale.items.forEach(x=>{NFCE['NFC-e 1002'].tax[x.code]=FISC.prod[x.bc]?{...FISC.prod[x.bc]}:undefined})")
    j=pg.evaluate("nfceBuild('NFC-e 1002').payload.items[0]")
    ok('JSON do regime normal: base 149,80 · ICMS 18% = 26,96 · PIS 0,97 · COFINS 4,49',j['icms_base_calculo']=='149.80' and j['icms_aliquota']=='18' and j['icms_valor']=='26.96' and j['pis_valor']=='0.97' and j['cofins_valor']=='4.49' and j['icms_modalidade_base_calculo']=='3')
    # ── persistência
    pg.reload();pg.wait_for_selector('#nav button',timeout=8000);pg.wait_for_timeout(500)
    ok('recarregar: matriz, checklist, CRT, CSC e NFC-e continuam salvos',pg.evaluate("FISC.prod[CAT[0][0]].cst=='00'&&FISC.chk.certVal=='2027-09-30'&&FISC.cscId=='1'&&EMP.ie=='0321418-40'&&!!NFCE['NFC-e 1001']&&T.fiscal.rows.some(r=>r[0]=='NFC-e 1002')"))
    ok('segredos NÃO são guardados no navegador (sem token, certificado ou CSC)',not any(w in json.dumps(pg.evaluate("[FISC,EMP,NFCE]")).lower() for w in ['senha_certificado','pfx','focusnfe_token','csc_token']))
    ok('todas as 15 abas continuam abrindo',pg.evaluate("NAV.every(([k])=>{show(k);return true})"))
    ok.done(errs)
